// revenue-conversion-fix.js
// Objective: Ensure paidEvents increments when a lead converts.
// This module hooks into the checkout flow and forces conversion tracking.

const fs = require('fs');
const path = require('path');

const REVENUE_LOG = '/var/log/revenue_events.log';

function trackConversion(leadId, amount) {
  const event = {
    ts: new Date().toISOString(),
    leadId,
    amount,
    type: 'paid'
  };
  fs.appendFileSync(REVENUE_LOG, JSON.stringify(event) + '\n');
  // Also update in-memory counter via a shared module if available
  try {
    const revenueTracker = require('./revenue-tracker');
    if (revenueTracker && revenueTracker.incrementPaid) {
      revenueTracker.incrementPaid(amount);
    }
  } catch (e) {
    // fallback: log only
  }
  return true;
}

// Expose for use in checkout completion handler
module.exports = { trackConversion };
